package com.aistock.notification.alert;
import com.aistock.common.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class NotificationAccessTest {
 @Test void mismatchedProfileAndDisabledAccountCannotGrantEmail(){var client=mock(NotificationIdentityClient.class);var owner=UUID.randomUUID();var access=new NotificationAccess(client,"internal");when(client.profile(anyString())).thenReturn(ApiResponse.success(new NotificationIdentityClient.Profile(UUID.randomUUID(),true,"ENABLED"),"trace"));assertEquals("ACCOUNT_SERVICE_UNAVAILABLE",assertThrows(BusinessException.class,()->access.emailVerified(owner,"session")).code());when(client.profile(anyString())).thenReturn(ApiResponse.success(new NotificationIdentityClient.Profile(owner,true,"DISABLED"),"trace"));assertThrows(BusinessException.class,()->access.emailVerified(owner,"session"));}
 @Test void missingServiceCredentialsDoNotResolveSession(){var client=mock(NotificationIdentityClient.class);assertThrows(BusinessException.class,()->new NotificationAccess(client,"").resolve("session"));verifyNoInteractions(client);}
 @Test void invalidOrUnavailableIdentityNeverDefaultsToUser(){var client=mock(NotificationIdentityClient.class);var access=new NotificationAccess(client,"internal");when(client.resolve(any(),anyString())).thenReturn(ApiResponse.success(null,"trace"));assertThrows(BusinessException.class,()->access.resolve("session"));when(client.resolve(any(),anyString())).thenThrow(new RuntimeException("private network detail"));var e=assertThrows(BusinessException.class,()->access.resolve("session"));assertFalse(e.getMessage().contains("private"));}
}
